{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score provides no evidence of consistency across runs."
        }
      ],
      "instrument_review": "The task set, scoring rule, and intended comparison are specified. The score describes this run on these puzzles; repeatability and the adequacy of conditions for fair system comparisons are not established."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated runs, score stability is untested; instability is also not demonstrated."
        }
      ],
      "instrument_review": "Exact-grid scoring supports reporting performance on the supplied puzzles. The documented absence of repetitions limits interpretation of consistency and confidence in comparisons based on a single run."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations explicitly held the stated conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "The repetitions support consistency under the specified conditions and stated stability criterion. They do not establish consistency for different puzzles or conditions, or performance beyond the intended grid-puzzle comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly assessed repeated performance under unchanged stated conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "The repeated evaluations document a consistency problem under the report's own criterion. The isolated 70% score is insufficient to characterize repeated performance; comparisons should account for the reported variation."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions provide no evidence that repeated-run testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No repeated-run findings are supplied to support stability."
        }
      ],
      "instrument_review": "The installation documentation explains setup but adds no evidence about score consistency. The reported score remains limited to one run; fair comparison conditions and repeatability remain insufficiently documented."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The supplied evidence does not establish comparative intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison fits the stated use of comparing performance on evaluated grid puzzles. Exact-grid scoring and fixed instructions support interpretation, while repeatability and other comparison conditions are not reported. Broader conclusions lack evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better performance by A on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The intended broad use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "The findings support a narrow grid-puzzle comparison, but the stated selection purpose exceeds the supplied evidence. Cross-domain findings are missing, and fixed instructions alone do not establish all conditions needed for a fair general comparison."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish improved decisions in the actual workshop."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied setting; the reported difference interval of 12 to 28 percentage points supports that direction."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The preregistered randomized trial, new cases, blinded correctness checks, and reported uncertainty strengthen support for the intended workshop correctness comparison. Findings are limited to the studied workshop and conditions; safety, time, and broader applicability remain unestablished."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence is classified as Not established; Contradicted is reserved for explicit conflict."
}
